/// Skill Drain: while it is face-up, monsters on the field have no effects.
pub const SKILL_DRAIN: u32 = 82732705;

/// Toon World by name: Toon Kingdom is treated as it while in the Field Zone.
pub const TOON_WORLDS: &[u32] = &[TOON_WORLD, TOON_KINGDOM];

/// "Every time", where a fact counts times in a turn.
pub const ALWAYS: u8 = u8::MAX;

/// Kinds of card whose effect is used on a monster, as a mask.
pub mod kind {
    pub const SPELL: u8 = 1;
    pub const TRAP: u8 = 2;
    pub const MONSTER: u8 = 4;
    pub const ALL: u8 = 7;
}

/// The attackers a fact holds against.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum Against {
    #[default]
    All,
    /// Attackers with at least this much ATK.
    AttackFrom(i32),
    /// Attackers with less ATK than this.
    AttackBelow(i32),
    /// Attackers of at least this Level.
    LevelFrom(u8),
    /// Attackers below this Level.
    LevelBelow(u8),
    /// Attackers of these Attributes (the card database's bits).
    Attributes(u8),
}

impl Against {
    pub fn holds(self, attack: i32, level: u32, attribute: u32) -> bool {
        match self {
            Against::All => true,
            Against::AttackFrom(n) => attack >= n,
            Against::AttackBelow(n) => attack < n,
            Against::LevelFrom(n) => level >= n as u32,
            Against::LevelBelow(n) => level < n as u32,
            Against::Attributes(mask) => attribute & mask as u32 != 0,
        }
    }
}

/// What becomes of a monster.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum Fate {
    #[default]
    Unharmed,
    Destroyed,
    Banished,
    /// To the hand or the Deck.
    Returned,
}

/// What a monster does to its attacker's ATK at damage calculation.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum AtkChange {
    #[default]
    None,
    Zero,
    Halved,
    Minus(i32),
}

impl AtkChange {
    pub fn apply(self, attack: i32) -> i32 {
        match self {
            AtkChange::None => attack,
            AtkChange::Zero => 0,
            AtkChange::Halved => (attack + 1) / 2,
            AtkChange::Minus(n) => (attack - n).max(0),
        }
    }
}

/// Damage the attacking player takes on top of the battle's own.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum Burn {
    #[default]
    None,
    Fixed(i32),
    /// As much as the attacker's ATK.
    AttackerAtk,
    /// The battle damage its controller would have taken.
    Reflected,
}

/// What an attack on a face-up monster meets, in one battle position.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Attacked {
    /// Battles a turn that do not destroy it though they should.
    pub survives: u8,
    /// Attacks a turn its controller can negate, and the Life Points each costs.
    pub negates: u8,
    pub negate_cost: i32,
    /// What becomes of the attacker, whatever the battle's result.
    pub attacker: Fate,
    /// ...before damage calculation: there is no battle, and no damage.
    pub before_damage: bool,
    /// It leaves the field along with the attacker.
    pub leaves: bool,
    /// ...and only when the battle destroys it (Newdoria), not whenever it
    /// battles (D.D. Warrior Lady).
    pub when_destroyed: bool,
    /// Change of its battle stat at damage calculation.
    pub stat: i32,
    pub attacker_atk: AtkChange,
    /// Its controller takes no battle damage.
    pub no_damage: bool,
    pub burn: Burn,
    /// Roughly what its controller gets back when the battle destroys it: a
    /// monster from the Deck, a card to the hand, tokens.
    pub payoff: i32,
    /// Other cards the attacking player loses then; [`ALWAYS`]: every monster.
    pub collateral: u8,
    /// Changes battle position when attacked.  The rest describes the
    /// position it ends up in.
    pub switches: bool,
    /// The attackers all of this holds against; others meet a plain monster.
    pub against: Against,
}

impl Attacked {
    pub const PLAIN: Attacked = Attacked {
        survives: 0,
        negates: 0,
        negate_cost: 0,
        attacker: Fate::Unharmed,
        before_damage: false,
        leaves: false,
        when_destroyed: false,
        stat: 0,
        attacker_atk: AtkChange::None,
        no_damage: false,
        burn: Burn::None,
        payoff: 0,
        collateral: 0,
        switches: false,
        against: Against::All,
    };
}

/// What a monster's own attack on a monster does.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Striking {
    /// ATK it gains in the Damage Step.
    pub bonus: i32,
    /// Inflicts piercing battle damage.
    pub piercing: bool,
    /// Can attack directly past the opponent's monsters.
    pub direct: bool,
    /// What becomes of the monster it attacks, whatever the battle's result.
    pub target: Fate,
    /// ...before damage calculation: there is no battle, and no damage.
    pub before_damage: bool,
    /// It leaves the field along with its target.
    pub leaves: bool,
    /// The targets `target` holds against, by their ATK, Level or Attribute.
    pub against: Against,
}

impl Striking {
    pub const PLAIN: Striking = Striking {
        bonus: 0,
        piercing: false,
        direct: false,
        target: Fate::Unharmed,
        before_damage: false,
        leaves: false,
        against: Against::All,
    };
}

/// What the facts about being attacked or destroyed depend on.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum Needs {
    #[default]
    Nothing,
    /// Its controller has no cards in hand (Infernity Guardian).
    EmptyHand,
    /// Unicore only negates while both players have the same hand size.
    EqualHands,
}

/// Facts about one card, as long as it is face-up.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Facts {
    /// Attacked in Attack Position, and in Defense Position.
    pub attacked: [Attacked; 2],
    /// What `attacked`, `immune` and `unaffected` depend on.
    pub needs: Needs,
    /// Its own attacks.
    pub striking: Striking,
    /// Kinds of effect that cannot target it.
    pub untargetable: u8,
    /// Kinds of effect its controller negates, whatever they do, at no cost.
    pub negates_any: u8,
    /// Kinds of effect its controller negates when they target it, and it
    /// stays on the field.
    pub negates_aimed: u8,
    /// Kinds of effect its controller negates when they would destroy it,
    /// targeting it or not, and it stays on the field.
    pub negates_destruction: u8,
    /// How many times a turn it negates.
    pub negate_times: u8,
    /// Each negation costs its controller a card from the hand.
    pub negate_discards: bool,
    /// Kinds of effect that cannot destroy it.
    pub immune: u8,
    /// Kinds of effect that do nothing to it.
    pub unaffected: u8,
    /// Roughly what its controller gets back when an effect destroys it.
    pub effect_payoff: i32,
    /// Other cards the player destroying it loses then; [`ALWAYS`]: every monster.
    pub effect_collateral: u8,
    /// Its coin decides whose effects that target it are negated and
    /// destroyed: heads its controller's, tails the opponent's (The Fool).
    pub coin_targeting_shield: bool,
}

impl Facts {
    pub const NONE: Facts = Facts {
        attacked: [Attacked::PLAIN; 2],
        needs: Needs::Nothing,
        striking: Striking::PLAIN,
        untargetable: 0,
        negates_any: 0,
        negates_aimed: 0,
        negates_destruction: 0,
        negate_times: 0,
        negate_discards: false,
        immune: 0,
        unaffected: 0,
        effect_payoff: 0,
        effect_collateral: 0,
        coin_targeting_shield: false,
    };

    /// The same in both battle positions.
    pub const fn attacked(attacked: Attacked) -> Facts {
        Facts { attacked: [attacked; 2], ..Facts::NONE }
    }
}

/// What the probes showed about a card of the pool.
pub fn probed(code: u32) -> Option<Facts> {
    pool::POOL.binary_search_by_key(&code, |(c, _)| *c).ok().map(|i| pool::POOL[i].1)
}

/// What we know about the card with this (canonical) code: what the probes
/// showed, and on top of it what they cannot.
pub fn facts(code: u32) -> Facts {
    const PLAIN: Attacked = Attacked::PLAIN;
    let mut facts = probed(code).unwrap_or(Facts::NONE);
    match code {
        // The coin is tossed when it is Summoned.
        THE_FOOL => facts.coin_targeting_shield = true,
        // Only with no cards in hand.
        INFERNITY_GUARDIAN => {
            facts.needs = Needs::EmptyHand;
            facts.attacked = [Attacked { survives: ALWAYS, ..PLAIN }; 2];
            facts.immune = kind::ALL;
        }
        // Its trigger needs a "Harpie Lady" in the Deck, a Morphtronic in
        // the hand or Graveyard: the staged Deck has neither.
        BIRDFACE => facts.attacked = [Attacked { payoff: 700, ..PLAIN }; 2],
        MORPHTRONIC_CAMERAN => facts.attacked[0].payoff = 1000,
        FABLED_UNICORE => {
            // The probe's particular hand sizes cannot establish an unconditional lock.
            facts = Facts { needs: Needs::EqualHands, negates_any: kind::ALL,
                negate_times: ALWAYS, ..Facts::NONE };
        }
        GUSTO_GULLDO | GUSTO_EGUL | GUSTO_WINDA => {
            // The probe's generic Deck contains no Gusto to recruit.
            facts.attacked = [Attacked { payoff: 1100, ..PLAIN }; 2];
            if code == GUSTO_GULLDO { facts.effect_payoff = 1100; }
        }
        _ => {}
    }
    facts
}

