#[cfg(test)]
mod tests {
    use super::*;

    /// `probed` searches the table by code.
    #[test]
    fn the_pool_table_is_sorted_by_code() {
        assert!(pool::POOL.windows(2).all(|w| w[0].0 < w[1].0));
        assert!(pool::POOL.iter().all(|(_, facts)| *facts != Facts::NONE));
    }

    #[test]
    fn conditions_on_the_attacker() {
        assert!(Against::All.holds(0, 0, 0));
        assert!(Against::AttackFrom(1900).holds(1900, 4, 1) && !Against::AttackFrom(1900).holds(1800, 4, 1));
        assert!(Against::LevelBelow(8).holds(1000, 7, 1) && !Against::LevelBelow(8).holds(1000, 8, 1));
        // Every Attribute but DARK (0x20).
        assert!(Against::Attributes(0x1f).holds(0, 0, 0x10) && !Against::Attributes(0x1f).holds(0, 0, 0x20));
    }
}
